    col_fg_count = {c: sum(1 for r in range(len(g_in)) if g_in[r][c] == fg) for c in range(len(g_in[0]))}
    multi_fg_cols = sorted([c for c, cnt in col_fg_count.items() if cnt >= 2])

    predictions = []

    # Top border
    for c in range(min_c, max_c + 1):
        if g_in[min_r][c] == bg:
            predictions.append((min_r, c))

    # Bottom border
    for c in range(min_c, max_c + 1):
        if g_in[max_r][c] == bg:
            predictions.append((max_r, c))

    # Left border
    for r in range(min_r, max_r + 1):
        if g_in[r][min_c] == bg:
            predictions.append((r, min_c))

    # Right border
    for r in range(min_r, max_r + 1):
        if g_in[r][max_c] == bg:
            predictions.append((r, max_c))

    # Fill gaps in multi-fg columns within bbox extent
    for c in multi_fg_cols:
        for r in range(min_r, max_r + 1):
            if g_in[r][c] == bg:
                predictions.append((r, c))

    return predictions, (min_r, max_r, min_c, max_c), multi_fg_cols

def get_actual(g_in, g_out):
    return set([(r,c) for r in range(len(g_in)) for c in range(len(g_in[0])) if g_in[r][c] != g_out[r][c]])

names = [("D1", d1_in, d1_out), ("D2", d2_in, d2_out), ("D3", d3_in, d3_out)]

for name, g_in, g_out in names:
    preds, bbox, multicols = get_prediction(g_in)
    actuals = get_actual(g_in, g_out)
    match = set(preds) == actuals
    print(f"\n{name}:")
    print(f"  bbox: {bbox}")
    print(f"  multi-fg-cols: {multicols}")
    print(f"  Predicted: {len(preds)}, Actual: {len(actuals)}, Match: {match}")
    if not match:
        print(f"  Missing: {actuals - set(preds)}")
        print(f"  Extra: {set(preds) - actuals}")
